/// <summary>
/// designed by AVANADE
/// </summary>
[ExtensionOf(formDataSourceStr(SalesCopying, CustQuotationJour))]
final class AVASalesCopyingFrmDS_Extension
{
    internal CurrencyCode        currencyCode;
    internal SalesTable          salesTable;
}

Method.Source:
/// <summary>
/// designed by AVANADE
/// </summary>
void init()
{
    SalesTable = this.formRun().args().record();
    CurrencyCode    = SalesTable.CurrencyCode;
    next init();
}

/// <summary>
/// designed by AVANADE
/// </summary>

void executeQuery()
{
    QueryBuildDataSource    qbds;
    QueryBuildRange         qbr;

    qbds = this.queryBuildDataSource();
    qbr = SysQuery::findOrCreateRange(qbds, fieldNum(CustQuotationJour, CurrencyCode));
    qbr.value(queryValue(CurrencyCode));

    next executequery();
}

/// <summary>
/// designed by AVANADE see also AVASalesCopyingQuotTransFrmDS_Extension
/// </summary>
/// <param name = "_set">boolean</param>
/// <param name = "_custQuotationJour">CustQuotationJour</param>
/// <param name = "_markAll">NoYes</param>
/// <returns>NoYes</returns>
edit NoYes  quotationMarkAll(boolean            _set,
                               CustQuotationJour    _custQuotationJour,
                               NoYes                _markAll)
{
    int numOfDays;
    if (_set && _markAll && _custQuotationJour.RespiteDate < DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
    {
        numOfDays   = date2Num(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())) - date2Num(_custQuotationJour.RespiteDate);
        Info(strFmt("@NDX:NXANumOfDaysWarning", numOfDays));
    }

    return next quotationMarkAll(_set, _custQuotationJour, _markAll);

}
